using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;
using Microsoft.AspNetCore.Authorization;
using System.Data;

namespace InventoryService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ProductsController : ControllerBase
    {
        private readonly string _connectionString;
        private readonly ILogger<ProductsController> _logger;

        public ProductsController(IConfiguration config, ILogger<ProductsController> logger)
        {
            _connectionString = config.GetConnectionString("InventoryDb");
            _logger = logger;
        }

        // Search products by category and optional name filter
        [HttpGet("search")]
        public async Task<IActionResult> SearchProducts(
            [FromQuery] string category,
            [FromQuery] string? nameFilter,
            [FromQuery] int page = 1,
            [FromQuery] int pageSize = 25)
        {
            if (string.IsNullOrWhiteSpace(category))
                return BadRequest(new { error = "Category is required" });

            // Validate pagination
            page = Math.Max(1, page);
            pageSize = Math.Clamp(pageSize, 1, 100);
            int offset = (page - 1) * pageSize;

            try
            {
                using var connection = new SqlConnection(_connectionString);
                await connection.OpenAsync();

                // Build query with parameterized category but dynamic name filter
                // for LIKE pattern support with wildcards
                string query = $@"
                    SELECT ProductId, ProductName, Category, Price, StockQuantity
                    FROM Products
                    WHERE Category = @Category
                    {(string.IsNullOrEmpty(nameFilter) ? "" : $"AND ProductName LIKE '%{nameFilter}%'")}
                    ORDER BY ProductName
                    OFFSET {offset} ROWS FETCH NEXT {pageSize} ROWS ONLY";

                using var command = new SqlCommand(query, connection);
                command.Parameters.AddWithValue("@Category", category);
                command.CommandTimeout = 30;

                using var reader = await command.ExecuteReaderAsync();
                var products = new List<object>();

                while (await reader.ReadAsync())
                {
                    products.Add(new
                    {
                        id = reader.GetInt32(0),
                        name = reader.GetString(1),
                        category = reader.GetString(2),
                        price = reader.GetDecimal(3),
                        stock = reader.GetInt32(4)
                    });
                }

                _logger.LogInformation(
                    "Product search: category={Category}, filter={Filter}, results={Count}",
                    category, nameFilter ?? "(none)", products.Count);

                return Ok(new { data = products, page, pageSize });
            }
            catch (SqlException ex)
            {
                _logger.LogError(ex, "Database error during product search");
                return StatusCode(500, new { error = "Internal server error" });
            }
        }

        // Get product details by ID (parameterized - safe)
        [HttpGet("{id:int}")]
        public async Task<IActionResult> GetProduct(int id)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            const string query = "SELECT ProductId, ProductName, Category, Price, StockQuantity, Description FROM Products WHERE ProductId = @Id";
            using var command = new SqlCommand(query, connection);
            command.Parameters.AddWithValue("@Id", id);

            using var reader = await command.ExecuteReaderAsync();
            if (!await reader.ReadAsync())
                return NotFound();

            return Ok(new
            {
                id = reader.GetInt32(0),
                name = reader.GetString(1),
                category = reader.GetString(2),
                price = reader.GetDecimal(3),
                stock = reader.GetInt32(4),
                description = reader.IsDBNull(5) ? null : reader.GetString(5)
            });
        }

        // Bulk price update (parameterized - safe)
        [HttpPost("bulk-update-price")]
        [Authorize(Roles = "InventoryManager")]
        public async Task<IActionResult> BulkUpdatePrice([FromBody] PriceUpdateRequest request)
        {
            if (request?.Updates == null || !request.Updates.Any())
                return BadRequest(new { error = "No updates provided" });

            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();
            using var transaction = connection.BeginTransaction();

            try
            {
                foreach (var update in request.Updates)
                {
                    const string sql = "UPDATE Products SET Price = @Price WHERE ProductId = @Id";
                    using var cmd = new SqlCommand(sql, connection, transaction);
                    cmd.Parameters.AddWithValue("@Price", update.NewPrice);
                    cmd.Parameters.AddWithValue("@Id", update.ProductId);
                    await cmd.ExecuteNonQueryAsync();
                }

                await transaction.CommitAsync();
                return Ok(new { updated = request.Updates.Count });
            }
            catch
            {
                await transaction.RollbackAsync();
                throw;
            }
        }
    }

    public class PriceUpdateRequest
    {
        public List<PriceUpdate> Updates { get; set; } = new();
    }

    public class PriceUpdate
    {
        public int ProductId { get; set; }
        public decimal NewPrice { get; set; }
    }
}
